58	  fn add_macro(&mut self, import: &ImportDecl) {
59	    for specifier in &import.specifiers {
60	      match specifier {
61	        ImportSpecifier::Named(named) => {
62	          let imported = match &named.imported {
63	            Some(imported) => match_export_name(imported).0.clone(),
64	            None => named.local.sym.clone(),
65	          };
66	          self.macros.insert(
67	            named.local.to_id(),
68	            MacroImport {
69	              src: import.src.value.clone(),
70	              imported: Some(imported),
71	            },
72	          );
73	        }
74	        ImportSpecifier::Default(default) => {
75	          self.macros.insert(
76	            default.local.to_id(),
77	            MacroImport {
78	              src: import.src.value.clone(),
79	              imported: Some(js_word!("default")),
80	            },
81	          );
82	        }
83	        ImportSpecifier::Namespace(namespace) => {
84	          self.macros.insert(
85	            namespace.local.to_id(),
86	            MacroImport {
87	              src: import.src.value.clone(),
88	              imported: None,
89	            },
90	          );
91	        }
92	      }
93	    }
94	  }
