106	  /// Convert a JsValue macro argument from the transformer to a napi value.
107	  fn js_value_to_napi(value: JsValue, env: Env) -> napi::Result<napi::JsUnknown> {
108	    match value {
109	      JsValue::Undefined => Ok(env.get_undefined()?.into_unknown()),
110	      JsValue::Null => Ok(env.get_null()?.into_unknown()),
111	      JsValue::Bool(b) => Ok(env.get_boolean(b)?.into_unknown()),
112	      JsValue::Number(n) => Ok(env.create_double(n)?.into_unknown()),
113	      JsValue::String(s) => Ok(env.create_string_from_std(s)?.into_unknown()),
114	      JsValue::Regex { source, flags } => {
115	        let regexp_class: JsFunction = env.get_global()?.get_named_property("RegExp")?;
116	        let source = env.create_string_from_std(source)?;
117	        let flags = env.create_string_from_std(flags)?;
118	        let re = regexp_class.new_instance(&[source, flags])?;
119	        Ok(re.into_unknown())
120	      }
121	      JsValue::Array(arr) => {
122	        let mut res = env.create_array(arr.len() as u32)?;
123	        for (i, val) in arr.into_iter().enumerate() {
124	          res.set(i as u32, js_value_to_napi(val, env)?)?;
125	        }
126	        Ok(res.coerce_to_object()?.into_unknown())
127	      }
128	      JsValue::Object(obj) => {
129	        let mut res = env.create_object()?;
130	        for (k, v) in obj {
131	          res.set_named_property(&k, js_value_to_napi(v, env)?)?;
132	        }
133	        Ok(res.into_unknown())
134	      }
135	      JsValue::Function(_) => {
136	        // Functions can only be returned from macros, not passed in.
137	        unreachable!()
138	      }
139	    }
140	  }
