fn handle_error(result: Result<Expr, MacroError>, errors: &mut Vec<MacroError>) -> Expr {
  match result {
    Ok(expr) => expr,
    Err(err) => {
      if !errors.iter().any(|d| *d == err) {
        errors.push(err);
      }
      Expr::Lit(Lit::Null(Null::dummy()))
    }
  }
}

