+
+      for (let {source, local, imported, loc} of hoist_result.re_exports) {
+        let dep = deps.get(source);
+        if (!dep) continue;
+        if (local === '*' && imported === '*') {
+          dep.symbols.set('*', '*', convertLoc(loc), true);
+        } else {
+          let reExportName =
